-- Innings ofensivos/defensivos (IO/ID) y dejados en base (QB) por juego.
-- Seguro de repetir: usa IF NOT EXISTS (MariaDB del VPS).
ALTER TABLE juegos
  ADD COLUMN IF NOT EXISTS io_local DECIMAL(5,2) NULL,
  ADD COLUMN IF NOT EXISTS id_local DECIMAL(5,2) NULL,
  ADD COLUMN IF NOT EXISTS io_visitante DECIMAL(5,2) NULL,
  ADD COLUMN IF NOT EXISTS id_visitante DECIMAL(5,2) NULL,
  ADD COLUMN IF NOT EXISTS qb_local INT NULL,
  ADD COLUMN IF NOT EXISTS qb_visitante INT NULL;

-- La tabla de posiciones usa IO/ID cargados a mano; si un juego no los tiene,
-- sigue calculándolos desde el pitcheo (innings lanzados) como antes.
CREATE OR REPLACE VIEW `vw_tabla_posiciones` AS SELECT `base`.`equipo_inscrito_id` AS `equipo_inscrito_id`, `base`.`temporada_categoria_id` AS `temporada_categoria_id`, `base`.`grupo` AS `grupo`, `base`.`equipo` AS `equipo`, `base`.`logo_url` AS `logo_url`, `base`.`jj` AS `jj`, `base`.`jg` AS `jg`, `base`.`jp` AS `jp`, `base`.`je` AS `je`, round(((`base`.`jg` / nullif(`base`.`jj`,0)) * 1000),0) AS `ave`, ((`base`.`jg` * 3) + `base`.`je`) AS `ptos`, round(((`base`.`jg` / nullif(`base`.`jj`,0)) * 100),0) AS `rend`, `base`.`carreras_anotadas` AS `carreras_anotadas`, `innings`.`ijo` AS `ijo`, round((`base`.`carreras_anotadas` / nullif(`innings`.`ijo`,0)),2) AS `media1`, `base`.`carreras_permitidas` AS `carreras_permitidas`, `innings`.`ijd` AS `ijd`, round((`base`.`carreras_permitidas` / nullif(`innings`.`ijd`,0)),2) AS `media2`, round(((`base`.`carreras_anotadas` / nullif(`innings`.`ijo`,0)) - (`base`.`carreras_permitidas` / nullif(`innings`.`ijd`,0))),2) AS `bce`, (`base`.`carreras_anotadas` - `base`.`carreras_permitidas`) AS `dc` FROM ((select `ei`.`id` AS `equipo_inscrito_id`,`ei`.`temporada_categoria_id` AS `temporada_categoria_id`,`ei`.`grupo` AS `grupo`,`e`.`nombre` AS `equipo`,`e`.`logo_url` AS `logo_url`,count(`j`.`id`) AS `jj`,sum((case when (((`j`.`equipo_local_id` = `ei`.`id`) and (`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1) and (`j`.`carreras_local` > `j`.`carreras_visitante`)) or ((`j`.`equipo_visitante_id` = `ei`.`id`) and (`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1) and (`j`.`carreras_visitante` > `j`.`carreras_local`)) or ((`j`.`estado` in ('ganado_forfeit','ganado_mesa','ganado_retiro')) and (`j`.`resultado_aprobado` = 1) and (`j`.`equipo_ganador_id` = `ei`.`id`))) then 1 else 0 end)) AS `jg`,sum((case when (((`j`.`equipo_local_id` = `ei`.`id`) and (`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1) and (`j`.`carreras_local` < `j`.`carreras_visitante`)) or ((`j`.`equipo_visitante_id` = `ei`.`id`) and (`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1) and (`j`.`carreras_visitante` < `j`.`carreras_local`)) or ((`j`.`estado` in ('ganado_forfeit','ganado_mesa','ganado_retiro')) and (`j`.`resultado_aprobado` = 1) and (`j`.`equipo_ganador_id` <> `ei`.`id`))) then 1 else 0 end)) AS `jp`,sum((case when ((`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1) and (`j`.`carreras_local` = `j`.`carreras_visitante`)) then 1 else 0 end)) AS `je`,sum((case when (`j`.`equipo_local_id` = `ei`.`id`) then coalesce(`j`.`carreras_local`,0) else coalesce(`j`.`carreras_visitante`,0) end)) AS `carreras_anotadas`,sum((case when (`j`.`equipo_local_id` = `ei`.`id`) then coalesce(`j`.`carreras_visitante`,0) else coalesce(`j`.`carreras_local`,0) end)) AS `carreras_permitidas` from ((`equipos_inscritos` `ei` join `equipos` `e` on((`e`.`id` = `ei`.`equipo_id`))) left join `juegos` `j` on((((`j`.`equipo_local_id` = `ei`.`id`) or (`j`.`equipo_visitante_id` = `ei`.`id`)) and (`j`.`estado` in ('jugado','ganado_forfeit','ganado_mesa','ganado_retiro')) and (`j`.`resultado_aprobado` = 1)))) group by `ei`.`id`,`ei`.`temporada_categoria_id`,`ei`.`grupo`,`e`.`nombre`,`e`.`logo_url`) `base` left join (select `ie`.`equipo_inscrito_id` AS `equipo_inscrito_id`,sum(coalesce(`ie`.`id_m`,`propio`.`il_total`,0)) AS `ijd`,sum(coalesce(`ie`.`io_m`,`rival`.`il_total`,0)) AS `ijo` from (((select `j`.`id` AS `juego_id`,`j`.`equipo_local_id` AS `equipo_inscrito_id`,`j`.`io_local` AS `io_m`,`j`.`id_local` AS `id_m` from `juegos` `j` where ((`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1)) union all select `j`.`id` AS `juego_id`,`j`.`equipo_visitante_id` AS `equipo_inscrito_id`,`j`.`io_visitante` AS `io_m`,`j`.`id_visitante` AS `id_m` from `juegos` `j` where ((`j`.`estado` = 'jugado') and (`j`.`resultado_aprobado` = 1))) `ie` left join (select `ep`.`juego_id` AS `juego_id`,`r`.`equipo_inscrito_id` AS `equipo_inscrito_id`,sum(`ep`.`il`) AS `il_total` from (`est_pitcheo` `ep` join `roster` `r` on((`r`.`id` = `ep`.`roster_id`))) where (`ep`.`aprobado` = 1) group by `ep`.`juego_id`,`r`.`equipo_inscrito_id`) `propio` on(((`propio`.`juego_id` = `ie`.`juego_id`) and (`propio`.`equipo_inscrito_id` = `ie`.`equipo_inscrito_id`)))) left join (select `ep`.`juego_id` AS `juego_id`,`r`.`equipo_inscrito_id` AS `equipo_inscrito_id`,sum(`ep`.`il`) AS `il_total` from (`est_pitcheo` `ep` join `roster` `r` on((`r`.`id` = `ep`.`roster_id`))) where (`ep`.`aprobado` = 1) group by `ep`.`juego_id`,`r`.`equipo_inscrito_id`) `rival` on(((`rival`.`juego_id` = `ie`.`juego_id`) and (`rival`.`equipo_inscrito_id` <> `ie`.`equipo_inscrito_id`)))) group by `ie`.`equipo_inscrito_id`) `innings` on((`innings`.`equipo_inscrito_id` = `base`.`equipo_inscrito_id`))) ;
